\title{Sharp Euler Prime Runs, Discriminants, and the Arithmetic Footprint of 163}
\author{Aristotle}
\date{24 July 2026}
\begin{document}
\maketitle

\begin{abstract}
For a nonnegative integer $p$, consider Euler's quadratic $f_p(n)=n^2+n+p$. We develop an elementary structural account of a sharp prime run, meaning that $f_p(n)$ is prime for every $0\le n<p-1$ and fails to be prime at $n=p-1$. The endpoint is universally forced: $f_p(p-1)=p^2$. Every sharp run for $p\ge2$ consists of exactly $p-1$ distinct primes in $[p,p^2)$; the parameter $p$ is prime; and, for $p\ge3$, $(p,p+2)$ is a twin-prime pair. Finite primality checks give sharp runs for $p=11,17,41$, of lengths $10,16,40$, with discriminant magnitudes $43,67,163$. We also establish three exact cube-plus-$744$ identities and their modular consequences, and show that $163$ is maximal in the explicitly specified set $\{1,2,3,7,11,19,43,67,163\}$. The scope of these elementary results is distinguished from the deeper class-number classification and transcendental near-integer estimates.
\end{abstract}

\section{Introduction}
The polynomial $f_{41}(n)=n^2+n+41$ is renowned because it is prime for every integer $n$ from $0$ through $39$. Its behavior is often discussed alongside the negative discriminant $-163$ and the near-integrality of $e^{\pi\sqrt{163}}$. Those themes belong to a broad theory involving binary quadratic forms, class numbers, modular functions, and complex multiplication. A substantial common arithmetic footprint can nevertheless be isolated using only integer identities, finite primality tests, and elementary inequalities.

We study $n^2+n+p$ uniformly in $p$. The index $p-1$ always produces $p^2$, creating a natural upper limit on an initial prime run. If every earlier value is prime, the run is sharp. From this one obtains parameter primality, a twin-prime pair, and an exact packing of primes below the square boundary. Completing the square,
\[
4f_p(n)=(2n+1)^2+(4p-1),
\]
then reveals the discriminant magnitude $4p-1$. For $p=11,17,41$, this gives $43,67,163$. These discriminants also correspond to exact cube-plus-$744$ integers associated classically with singular moduli.

\section{Definitions and the square boundary}
\begin{definition}[Euler quadratic]
For $p,n\in\N$, define
\[
f_p(n)=n^2+n+p=p+n(n+1).
\]
\end{definition}

\begin{definition}[Sharp Euler prime run]
A parameter $p$ has a sharp Euler prime run if $f_p(n)$ is prime for every $0\le n<p-1$ and $f_p(p-1)$ is not prime. For $p\ge2$, the proper indices are $0,1,\ldots,p-2$.
\end{definition}

\begin{definition}[Discriminant magnitude and run-value set]
Set
\[
D_p=4p-1,
\qquad
R_p=\{f_p(n):0\le n<p-1\}.
\]
The discriminant of $x^2+x+p$ is $1-4p=-D_p$.
\end{definition}

\begin{definition}[Explicit Heegner list]
In this paper the explicit Heegner list means only the finite set
\[
H=\{1,2,3,7,11,19,43,67,163\}.
\]
The name does not itself assert a class-number characterization.
\end{definition}

\begin{lemma}[Square boundary]
If $p\ge1$, then $f_p(p-1)=p^2$.
\end{lemma}
\begin{proof}
Direct expansion gives
\[
(p-1)^2+(p-1)+p=p^2-2p+1+p-1+p=p^2.
\]
\end{proof}

\begin{corollary}[Universal endpoint obstruction]
If $p\ge2$, then $f_p(p-1)$ is composite. No initial prime run can include every index through $p-1$.
\end{corollary}
\begin{proof}
The endpoint is $p^2=p\cdot p$, a nontrivial factorization when $p\ge2$.
\end{proof}

\section{Monotonicity and interval geometry}
\begin{lemma}[Strict increase]
For every $p\in\N$, the sequence $n\mapsto f_p(n)$ is strictly increasing and hence injective.
\end{lemma}
\begin{proof}
For $n\ge0$,
\[
f_p(n+1)-f_p(n)=2n+2>0.
\]
More generally, if $a<b$, then $f_p(b)-f_p(a)=(b-a)(a+b+1)>0$.
\end{proof}

\begin{lemma}[Proper values lie below the square]
If $p,n\in\N$ and $n+2\le p$, then
\[
p\le f_p(n)<p^2.
\]
\end{lemma}
\begin{proof}
The lower bound follows from $f_p(n)=p+n(n+1)$. Since $n<p-1$, strict increase and the square-boundary lemma give $f_p(n)<f_p(p-1)=p^2$.
\end{proof}

The successive gaps are forced:
\[
f_p(n+1)-f_p(n)=2n+2.
\]
Thus the values rise with gaps $2,4,6,\ldots$ and form the translate by $p$ of the convex sequence $n(n+1)$.

\section{Structural consequences}
\begin{theorem}[Parameter primality]
Let $p\ge2$. If $p$ has a sharp Euler prime run, then $p$ is prime.
\end{theorem}
\begin{proof}
The run includes index $0$, and $f_p(0)=p$.
\end{proof}

\begin{theorem}[Twin-prime consequence]
Let $p\ge3$. If $p$ has a sharp Euler prime run, then $p$ and $p+2$ are prime.
\end{theorem}
\begin{proof}
The preceding theorem makes $p$ prime. Since $1<p-1$, the run includes index $1$, where $f_p(1)=p+2$.
\end{proof}

\begin{remark}
The assumption $p\ge3$ is necessary. For $p=2$, index $1$ is already the square boundary, and $p+2=4$ is composite.
\end{remark}

\begin{theorem}[Sharp-run prime packing]
Let $p\ge2$ have a sharp Euler prime run. Then $R_p$ has cardinality $p-1$, every member of $R_p$ is prime, and every $m\in R_p$ satisfies $p\le m<p^2$. Thus the run supplies exactly $p-1$ distinct primes in $[p,p^2)$.
\end{theorem}
\begin{proof}
The index set $\{0,1,\ldots,p-2\}$ has $p-1$ elements. Strict increase gives distinct images, the run hypothesis gives primality, and the interval lemma supplies the bounds.
\end{proof}

\begin{corollary}[Forced arithmetic ladder]
Under the preceding hypotheses,
\[
R_p=\{p+k(k+1):0\le k\le p-2\},
\]
and all displayed values are prime and distinct.
\end{corollary}
\begin{proof}
Combine $f_p(k)=p+k(k+1)$ with the sharp-run hypothesis and injectivity.
\end{proof}

The packing theorem constructs a distinguished subset of primes in the interval; it does not claim that these are all primes in $[p,p^2)$.

\section{The runs associated with 43, 67, and 163}
\begin{theorem}[Discriminant-$43$ run]
The polynomial $n^2+n+11$ is prime for $0\le n\le9$, and its next value is $f_{11}(10)=121$. It has a sharp ten-term run.
\end{theorem}
\begin{proof}
The values are
\[
11,13,17,23,31,41,53,67,83,101.
\]
Trial division by primes up to each square root proves primality. The boundary is $11^2=121$.
\end{proof}

\begin{theorem}[Discriminant-$67$ run]
The polynomial $n^2+n+17$ is prime for $0\le n\le15$, and $f_{17}(16)=289$. It has a sharp sixteen-term run.
\end{theorem}
\begin{proof}
The proper values are
\[
17,19,23,29,37,47,59,73,89,107,127,149,173,199,227,257.
\]
Finite trial division proves them prime, and the boundary is $17^2=289$.
\end{proof}

\begin{theorem}[Discriminant-$163$ run]
The polynomial $n^2+n+41$ is prime for $0\le n\le39$, and $f_{41}(40)=1681$. It has a sharp forty-term run.
\end{theorem}
\begin{proof}
Generate the forty values $41+n(n+1)$ and test divisibility by primes no larger than each square root. None has a proper divisor. The sequence begins $41,43,47,53,61,71$ and its final proper value is $1601$. The boundary is $41^2=1681$.
\end{proof}

\begin{corollary}[Twin pairs and packings]
The pairs $(11,13)$, $(17,19)$, and $(41,43)$ are twin-prime pairs. The corresponding runs contain $10$, $16$, and $40$ distinct primes in $[11,121)$, $[17,289)$, and $[41,1681)$, respectively.
\end{corollary}
\begin{proof}
Apply the twin-prime and packing theorems to the three sharp runs.
\end{proof}

\section{Discriminant correspondence}
Completing the square gives
\[
4f_p(n)=4n^2+4n+4p=(2n+1)^2+(4p-1).
\]
This identifies $D_p=4p-1$ as the magnitude of the negative discriminant.

\begin{theorem}[Exact discriminant correspondence]
The parameters $11$, $17$, and $41$ have discriminant magnitudes
\[
D_{11}=43,\qquad D_{17}=67,\qquad D_{41}=163.
\]
\end{theorem}
\begin{proof}
Substitution gives $4\cdot11-1=43$, $4\cdot17-1=67$, and $4\cdot41-1=163$.
\end{proof}

This identity is an elementary bridge to imaginary quadratic orders. It does not prove that any such order has class number one; that requires ideal classes or reduced binary quadratic forms.

\section{Exact cube-plus-744 arithmetic}
\begin{theorem}[Cube-plus-$744$ identities]
The following exact integer identities hold:
\[
960^3+744=884736744,
\]
\[
5280^3+744=147197952744,
\]
\[
640320^3+744=262537412640768744.
\]
\end{theorem}
\begin{proof}
Direct multiplication gives the cubes $884736000$, $147197952000$, and $262537412640768000$. Adding $744$ gives the stated integers.
\end{proof}

\begin{corollary}[Common modular signature]
One has
\[
884736744\bmod 960^3=744,
\quad
147197952744\bmod 5280^3=744,
\]
\[
262537412640768744\bmod 640320^3=744.
\]
\end{corollary}
\begin{proof}
Each integer is $a^3+744$, with $0\le744<a^3$, so division by $a^3$ leaves remainder $744$.
\end{proof}

In the analytic theory, $744$ is the constant term in $j(q)=q^{-1}+744+196884q+\cdots$. The exact identities are arithmetic endpoints. Rigorous estimates involving $e^{\pi\sqrt D}$ additionally require singular-modulus identities and controlled bounds on the remaining series terms.

\section{The explicit finite list}
\begin{theorem}[Finite-list maximality]
For $H=\{1,2,3,7,11,19,43,67,163\}$, the values $43$, $67$, and $163$ belong to $H$, and $163$ is its maximum.
\end{theorem}
\begin{proof}
Membership is immediate from the display. Every listed element is at most $163$, and $163$ itself is present.
\end{proof}

\begin{remark}
This is a theorem about a specified finite set. It is not the Stark--Heegner classification that these are precisely the class-number-one imaginary quadratic discriminants.
\end{remark}

\section{Algorithms and computation}
For $m\ge2$, trial division tests candidates through $\lfloor\sqrt m\rfloor$. A composite integer has a factor no larger than its square root. To test sharpness, evaluate $f_p(n)$ for $0\le n<p-1$, test each value, and verify the square boundary. Since there are $O(p)$ values below $p^2$ and each takes $O(p)$ candidate divisions in the simplest implementation, the straightforward cost is $O(p^2)$ divisibility tests. Streaming requires constant auxiliary storage; retaining the run uses $O(p)$ storage.

The run-value set is generated in sorted order by computing $p+n(n+1)$ for $n=0,\ldots,p-2$. Strict monotonicity eliminates duplicate checks. Cube signatures are checked with exact integer exponentiation, addition, and remainder, so they incur no floating-point error.

\section{Applications, boundaries, and future directions}
A sharp run gives a constructive lower bound on prime density in $[p,p^2)$. It also supplies immediate obstructions: if $p$ or $p+2$ is composite for $p\ge3$, sharpness is impossible. More generally, for a small prime $q$, solutions of
\[
n^2+n+p\equiv0\pmod q
\]
identify forbidden residue classes of indices. The square boundary is the special case $q=p$, $n=p-1$.

The discriminant identity points toward Rabinowitsch's criterion, relating full primality of $n^2+n+p$ on $0\le n\le p-2$ to class number one for discriminant $1-4p$. The prime-run side and its consequences have been established here for $p=11,17,41$; the equivalence itself has not.

Several distinctions are essential. Exact cube identities do not alone prove bounds on $e^{\pi\sqrt D}$. Maximality in the nine-element displayed set is not an unbounded classification. The packing contains $p-1$ selected primes but need not contain all interval primes. Finally, no unrestricted uniqueness claim about near-integrality of $e^{\pi\sqrt n}$ follows; any credible uniqueness theorem should specify a bounded range or structural hypotheses.

Future work includes deriving explicit prime-counting lower bounds from the packing, developing modular sieves for early failures, proving the Rabinowitsch equivalence through reduced binary quadratic forms, and constructing the analytic bridge through the modular $j$-invariant with rigorous tail estimates. Certified interval bounds for $\pi$, square roots, and exponentials would support bounded near-integer searches without relying on floating-point output.

\section{Conclusion}
The universal identity $f_p(p-1)=p^2$ turns a long prime run into a rigid object. A sharp run forces parameter primality, produces a twin-prime pair for $p\ge3$, and packs exactly $p-1$ distinct primes into $[p,p^2)$. The parameters $11$, $17$, and $41$ realize runs of lengths $10$, $16$, and $40$; completing the square associates them with $43$, $67$, and $163$. Exact cube-plus-$744$ identities add a common modular signature, while $163$ is maximal in the explicit nine-element set. This is an elementary chain from Euler's quadratic to the arithmetic footprint of $163$, ending exactly where the deeper class-number and transcendental theories begin.

\end{document}

