from math import isqrt

def prime(n: int) -> bool:
    if n < 2: return False
    return all(n % d for d in range(2, isqrt(n) + 1))

def run(p: int) -> list[int]:
    return [n*n+n+p for n in range(p-1)]

for p in (11, 17, 41):
    values = run(p)
    assert all(prime(v) for v in values)
    assert len(set(values)) == p-1
    assert all(p <= v < p*p for v in values)
    assert (p-1)**2 + (p-1) + p == p*p
    print(p, 4*p-1, len(values), values[0], values[-1], p*p)

from math import isqrt

def prime(n: int) -> bool:
    if n < 2: return False
    return all(n % d for d in range(2, isqrt(n) + 1))

for p in (11, 17, 41):
    first = p
    second = p + 2
    assert prime(first) and prime(second)
    print(f"p={p}: ({first}, {second}) is a twin-prime pair")

