from math import isqrt

def sharp_run_report(p: int) -> dict[str, object]:
    if p < 2: raise ValueError("p must be at least 2")
    def prime(m: int) -> bool:
        if m < 2: return False
        return all(m % d for d in range(2, isqrt(m) + 1))
    values = [n*n+n+p for n in range(p-1)]
    boundary = (p-1)**2 + (p-1) + p
    return {"p": p, "values": values, "sharp": all(map(prime, values)) and not prime(boundary), "boundary": boundary}

def prime_packing(p: int) -> tuple[int, ...]:
    if p < 2: raise ValueError("p must be at least 2")
    values = tuple(p + n*(n+1) for n in range(p-1))
    assert len(values) == len(set(values)) == p-1
    assert all(p <= value < p*p for value in values)
    return values

def cube_signature(base: int, target: int) -> dict[str, int | bool]:
    cube = base ** 3
    return {"base": base, "target": target, "exact": cube + 744 == target, "remainder": target % cube}

for pair in ((960, 884736744), (5280, 147197952744), (640320, 262537412640768744)):
    print(cube_signature(*pair))

